from pathlib import Path
HERE=Path(__file__).resolve().parent.parent
def run(cmd,*,cwd=HERE,env=None):
 r=subprocess.run(list(map(str,cmd)),cwd=cwd,capture_output=True,env=env);assert r.returncode==0,(cmd,r.returncode,r.stdout[-2000:],r.stderr[-8000:]);return r.stdout
HOST=r'''
#include "network_engine_transport.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define CHECK(x) check((x),__LINE__)
static void check(bool ok,int line){if(!ok){fprintf(stderr,"transport check failed at %d\n",line);exit(1);}}
static const NetworkEngineMac LOCAL={{0x52,0x54,0,0x12,0x34,0x56}},PEER={{2,0,0,0,0,1}},GATEWAY={{2,0,0,0,0,2}};
static void p16(NetworkEngineFrame *f,size_t n,uint16_t v){f->bytes[n]=(uint8_t)(v>>8);f->bytes[n+1]=(uint8_t)v;}static void p32(NetworkEngineFrame *f,size_t n,uint32_t v){f->bytes[n]=(uint8_t)(v>>24);f->bytes[n+1]=(uint8_t)(v>>16);f->bytes[n+2]=(uint8_t)(v>>8);f->bytes[n+3]=(uint8_t)v;}
static NetworkEngineFrame arp(uint32_t sender,uint32_t target,NetworkEngineMac mac,bool reply){NetworkEngineFrame f={0};f.length=60;for(size_t i=0;i<6;i++){f.bytes[i]=reply?LOCAL.bytes[i]:255;f.bytes[6+i]=mac.bytes[i];f.bytes[22+i]=mac.bytes[i];f.bytes[32+i]=reply?LOCAL.bytes[i]:255;}p16(&f,12,0x0806);p16(&f,14,1);p16(&f,16,0x0800);f.bytes[18]=6;f.bytes[19]=4;p16(&f,20,reply?2:1);p32(&f,28,sender);p32(&f,38,target);return f;}
static NetworkEnginePayload payload(size_t n,uint8_t salt){NetworkEnginePayload p={0};p.len=n;for(size_t i=0;i<n;i++)p.bytes[i]=(uint8_t)(i*13+salt);return p;}
static NetworkTcpPacket take_tcp(NetworkEngineTransport *e){NetworkEngineFrameResult r=network_engine_transport_take_frame(e);CHECK(r.present);NetworkTcpPacket t=network_engine_tcp_decode(&r.frame);CHECK(t.valid);return t;}
static NetworkTcpPacket connect(NetworkEngineTransport *e,NetConfig c,uint32_t ticket,NetworkEngineMac next_mac,uint32_t next_ip,uint64_t now){CHECK(network_engine_transport_begin_client(e,ticket,false)==0);network_engine_transport_advance(e,now);NetworkEngineFrameResult query=network_engine_transport_take_frame(e);CHECK(query.present);NetworkArpPacket a=network_engine_arp_decode(&query.frame);CHECK(a.valid&&a.operation==1&&a.target_ip==next_ip);NetworkEngineFrame reply=arp(next_ip,c.local,next_mac,true);CHECK(network_engine_transport_submit(e,&reply)==0);network_engine_transport_advance(e,now+1);NetworkTcpPacket syn=take_tcp(e);CHECK((syn.flags&NETWORK_TCP_SYN)!=0&&syn.source_port==c.source_base+ticket);NetworkEnginePayload empty={0};NetworkEngineFrame synack={0};CHECK(network_engine_tcp_build(&synack,e->base.mac,next_mac,e->client.remote_ip,e->client.local_ip,e->client.remote_port,e->client.local_port,900,syn.sequence+1,NETWORK_TCP_SYN|NETWORK_TCP_ACK,8192,&empty));CHECK(network_engine_transport_submit(e,&synack)==0);network_engine_transport_advance(e,now+2);NetworkTcpPacket ack=take_tcp(e);CHECK(ack.flags==NETWORK_TCP_ACK&&e->client.state==NETWORK_TCP_ESTABLISHED);return syn;}
static void onlink_handshake_data_close(void){NetworkEngineTransport e;NetConfig c=net_config_controlled();CHECK(network_engine_transport_init(&e,c,LOCAL,0)==0);connect(&e,c,1,PEER,c.http,1);NetworkEnginePayload out=payload(256,3);CHECK(network_engine_transport_client_send(&e,&out).count==256);network_engine_transport_advance(&e,4);NetworkTcpPacket data=take_tcp(&e);CHECK(data.payload_length==256);NetworkEnginePayload empty={0};NetworkEngineFrame ack={0};CHECK(network_engine_tcp_build(&ack,e.base.mac,PEER,e.client.remote_ip,e.client.local_ip,e.client.remote_port,e.client.local_port,e.client.rcv_nxt,e.client.pending_end,NETWORK_TCP_ACK,8192,&empty));CHECK(network_engine_transport_submit(&e,&ack)==0);network_engine_transport_advance(&e,5);CHECK(network_engine_transport_client_queued(&e)==0);
 NetworkEnginePayload incoming=payload(200,7);NetworkEngineFrame peerdata={0};CHECK(network_engine_tcp_build(&peerdata,e.base.mac,PEER,e.client.remote_ip,e.client.local_ip,e.client.remote_port,e.client.local_port,e.client.rcv_nxt,e.client.snd_nxt,NETWORK_TCP_PSH|NETWORK_TCP_ACK,8192,&incoming));CHECK(network_engine_transport_submit(&e,&peerdata)==0);network_engine_transport_advance(&e,6);CHECK(take_tcp(&e).flags==NETWORK_TCP_ACK);NetworkTcpClientReceive got=network_engine_transport_client_receive(&e,256);CHECK(got.ok&&got.count==200&&!memcmp(got.bytes,incoming.bytes,200));network_engine_transport_client_finish(&e);network_engine_transport_advance(&e,7);CHECK((take_tcp(&e).flags&NETWORK_TCP_FIN)!=0);}
static void offlink_gateway_and_exclusion(void){NetworkEngineTransport e;NetConfig c=net_config_controlled();c.dns=0xc6336435;c.http=0xcb007109;CHECK(network_engine_transport_init(&e,c,LOCAL,0)==0);connect(&e,c,9,GATEWAY,c.gateway,1);CHECK(e.client.remote_ip==c.http);CHECK(network_engine_transport_begin_dns(&e,1)==NETWORK_ENGINE_BUSY);network_engine_transport_client_abort(&e);(void)network_engine_transport_take_frame(&e);CHECK(network_engine_transport_begin_dns(&e,1)==0);CHECK(network_engine_transport_begin_client(&e,2,false)==NETWORK_ENGINE_BUSY);network_engine_transport_dns_abort(&e);CHECK(network_engine_transport_begin_client(&e,2,false)==0);}
static void backpressure_abort_ownership_and_clock(void){NetworkEngineTransport e;NetConfig c=net_config_controlled();CHECK(network_engine_transport_init(&e,c,LOCAL,0)==0);CHECK(network_engine_transport_begin_client(&e,1,false)==0);network_engine_transport_advance(&e,1);CHECK(network_engine_transport_has_frame(&e));NetworkEngineFrame request=arp(0x0a000220,c.local,(NetworkEngineMac){{2,0,0,0,0,32}},false);CHECK(network_engine_transport_submit(&e,&request)==0);network_engine_transport_advance(&e,2);CHECK(!network_engine_transport_can_receive(&e));(void)network_engine_transport_take_frame(&e);network_engine_transport_advance(&e,3);CHECK(network_engine_transport_has_frame(&e));network_engine_transport_client_abort(&e);NetworkEngineFrameResult reply=network_engine_transport_take_frame(&e);CHECK(reply.present&&network_engine_arp_decode(&reply.frame).valid);
 CHECK(network_engine_transport_begin_client(&e,2,false)==0);
 network_engine_transport_advance(&e,1001);
 CHECK(network_engine_transport_has_frame(&e));
 network_engine_transport_advance(&e,1000);
 CHECK(e.base.stopped&&e.base.failure==NETWORK_ENGINE_CLOCK&&!network_engine_transport_has_frame(&e));}
static void abort_replaces_own_tcp_with_reset(void){NetworkEngineTransport e;NetConfig c=net_config_controlled();CHECK(network_engine_transport_init(&e,c,LOCAL,0)==0);connect(&e,c,4,PEER,c.http,1);NetworkEnginePayload p=payload(8,1);CHECK(network_engine_transport_client_send(&e,&p).ok);network_engine_transport_advance(&e,4);CHECK(e.base.tx_kind==NETWORK_ENGINE_TX_TCP);network_engine_transport_client_abort(&e);NetworkTcpPacket reset=take_tcp(&e);CHECK((reset.flags&NETWORK_TCP_RST)!=0&&reset.source_port==c.source_base+4);}
static void wait_requires_neighbor_hit(void){NetworkEngineTransport e;NetConfig c=net_config_controlled();CHECK(network_engine_transport_init(&e,c,LOCAL,0)==0);CHECK(network_engine_transport_begin_client(&e,8,false)==0);network_engine_transport_advance(&e,1);CHECK(network_engine_transport_take_frame(&e).present);network_engine_transport_advance(&e,2);CHECK(e.client_pending&&!e.base.stopped&&!network_engine_transport_has_frame(&e));}
static void listener_and_client_share_one_frame(void){NetworkEngineTransport e;NetConfig c=net_config_controlled();CHECK(network_engine_transport_init(&e,c,LOCAL,0)==0);connect(&e,c,6,PEER,c.http,1);NetworkEnginePayload empty={0};NetworkEngineFrame syn={0};CHECK(network_engine_tcp_build(&syn,e.base.mac,PEER,c.http,c.local,62000,c.listen_port,100,0,NETWORK_TCP_SYN,4096,&empty));CHECK(network_engine_transport_submit(&e,&syn)==0);network_engine_transport_advance(&e,4);NetworkTcpPacket synack=take_tcp(&e);CHECK(synack.source_port==c.listen_port);NetworkEngineFrame ack={0};CHECK(network_engine_tcp_build(&ack,e.base.mac,PEER,c.http,c.local,62000,c.listen_port,101,synack.sequence+1,NETWORK_TCP_ACK,4096,&empty));CHECK(network_engine_transport_submit(&e,&ack)==0);network_engine_transport_advance(&e,5);CHECK(e.listener.state==NETWORK_LISTENER_ESTABLISHED);NetworkEnginePayload echo=payload(64,9);NetworkEngineFrame data={0};CHECK(network_engine_tcp_build(&data,e.base.mac,PEER,c.http,c.local,62000,c.listen_port,101,e.listener.snd_nxt,NETWORK_TCP_PSH|NETWORK_TCP_ACK,4096,&echo));CHECK(network_engine_transport_submit(&e,&data)==0);network_engine_transport_advance(&e,6);CHECK(take_tcp(&e).destination_port==62000);NetworkEnginePayload client=payload(32,3);CHECK(network_engine_transport_client_send(&e,&client).ok);network_engine_transport_advance(&e,7);NetworkTcpPacket first=take_tcp(&e);CHECK(first.destination_port==c.http_port&&first.payload_length==32);network_engine_transport_advance(&e,8);NetworkTcpPacket second=take_tcp(&e);CHECK(second.destination_port==62000&&second.payload_length==64);}
int main(void){onlink_handshake_data_close();offlink_gateway_and_exclusion();backpressure_abort_ownership_and_clock();abort_replaces_own_tcp_with_reset();wait_requires_neighbor_hit();listener_and_client_share_one_frame();puts("PASS composed transport routing custody exclusion listener TCP and clock controls");return 0;}
'''
def main():
 p=argparse.ArgumentParser();p.add_argument('--cesta',type=Path,required=True);p.add_argument('--cesta-source',type=Path);p.add_argument('--lean-root',type=Path);p.add_argument('--output',type=Path,default=HERE/'build/network-engine-transport-tests');a=p.parse_args();w=a.output.resolve();w.mkdir(parents=True,exist_ok=True);inv=json.loads((HERE/'interfaces/network_engine_transport.source.json').read_text())
 for path,key in ((inv['library_path'],'library_sha256'),(inv['tests_path'],'tests_sha256')):actual=run(['git','show',f"{inv['pin']}:{path}"],cwd=HERE.parent);assert hashlib.sha256(actual).hexdigest()==inv[key]
 cargo=run(['cargo','test','-p','sex-net','--lib','--','--test-threads=1'],cwd=HERE.parent);assert b'54 passed' in cargo;host=w/'host.c';host.write_text(HOST);exports={};plans={};configs=[];names=('network_config','network_engine_frame','network_engine_packet','network_engine_tcp_packet','network_tcp_client','network_tcp_listener','network_engine_neighbor','network_dns_codec','network_engine_dns','network_engine_transport')
 for cc in ('gcc','clang'):
  sources=[]
  for name in names:
   out=w/f'{name}-{cc}.c';cmd=[a.cesta,'export-c',f'src/{name}.cesta','--cc',cc,'--std=c11','-o',out]
   if name=='network_engine_transport':plan=w/f'{name}-{cc}.plan';cmd.extend(['--plan',plan]);exports[cc]=out;plans[cc]=plan
   run(cmd+['--','-Igenerated/include']);sources.append(out)
  for mode,flags in (('O0',['-O0']),('O2',['-O2']),('SAN',['-O1','-fsanitize=address,undefined','-fno-sanitize-recover=all','-fno-pie','-no-pie'])):
   b=w/f'{cc}-{mode}';run([cc,'-std=c11','-Wall','-Wextra','-Wpedantic','-Werror',*flags,'-Igenerated/include',*sources,host,'-o',b]);actual=run([b],env={**os.environ,'ASAN_OPTIONS':'detect_leaks=1:abort_on_error=1'});configs.append({'compiler':cc,'mode':mode,'sha256':hashlib.sha256(actual).hexdigest()})
 base=exports['gcc'].read_text();mutations=[('clock-before-backpressure','if(now<engine->base.last','if(false&&now<engine->base.last'),('dns-exclusion','if(engine->base.dns_active)return NETWORK_ENGINE_BUSY','if(false)return NETWORK_ENGINE_BUSY'),('client-exclusion','if(engine->client_pending||engine->client.state!=NETWORK_TCP_CLOSED)','if(false)'),('discover-arp','neighbor.kind==NETWORK_NEIGHBOR_DISCOVER','false'),('tcp-ingress','if(tcp.valid)transport_tcp_ingress','if(false)transport_tcp_ingress'),('listener-ingress','if(!consumed)(void)network_tcp_listener_ingest','if(false)(void)network_tcp_listener_ingest'),('listener-egress','NetworkTcpListenerOutput output=network_tcp_listener_advance','NetworkTcpListenerOutput output=(NetworkTcpListenerOutput){0};(void)network_tcp_listener_advance'),('abort-own-frame','engine->base.tx_kind==NETWORK_ENGINE_TX_TCP&&engine->base.tx_ticket==ticket','true'),('route-hit','neighbor.kind!=NETWORK_NEIGHBOR_HIT','false')];caught=[];prefix=[w/f'{n}-gcc.c' for n in names[:-1]]
 for name,old,new in mutations:
  assert base.count(old)>=1,(name,base.count(old));m=w/f'mutant-{name}.c';m.write_text(base.replace(old,new));b=w/f'mutant-{name}';run(['gcc','-std=c11','-O2','-Igenerated/include',*prefix,m,host,'-o',b]);r=subprocess.run([b],cwd=HERE,capture_output=True);assert r.returncode!=0,('survived',name,r.stdout,r.stderr);caught.append(name)
 admission=[]
 if a.lean_root:
  assert a.cesta_source;sys.path.insert(0,str(a.cesta_source.resolve()/'tests'));h=importlib.import_module('ownership_admission');unique={}
  for plan in plans.values():unique[hashlib.sha256(plan.read_bytes()).hexdigest()]=plan
  for i,plan in enumerate(unique.values()):(record,)=h.parse(plan.read_bytes());admission.append(h.admit_record(record,w/f'Transport{i}.lean',a.lean_root.resolve()))
 (w/'summary.json').write_text(json.dumps({'pin':inv['pin'],'upstream_rust_tests':54,'configurations':configs,'mutants_caught':caught,'admission':admission},indent=2)+'\n');print('network engine transport:',len(configs),'configurations;',len(caught),'mutants;',sum(x['functions'] for x in admission),'plans admitted')
if __name__=='__main__':main()
